func main() {
	fast := make(chan string)
	slow := make(chan string)

	go func() {
		time.Sleep(20 * time.Millisecond)
		fast <- "fast"
	}()
	go func() {
		time.Sleep(150 * time.Millisecond)
		slow <- "slow"
	}()

	for range 2 {
		select {
		case msg := <-fast:
			fmt.Println(msg)
		case msg := <-slow:
			fmt.Println(msg)
		case <-time.After(200 * time.Millisecond):
			fmt.Println("timeout")
			return
		}
	}
}

