import (
	"fmt"
	"time"
)

func main() {
	queue := make(chan int, 1)

	select {
	case queue <- 5:
		fmt.Println("queued")
	default:
		fmt.Println("queue full, drop")
	}

	ticker := time.NewTicker(50 * time.Millisecond)
	quit := make(chan struct{})
	go func() {
		time.Sleep(120 * time.Millisecond)
		close(quit)
	}()

	for {
		select {
		case tick := <-ticker.C:
			fmt.Println("tick", tick.Format("15:04:05.000"))
		case <-quit:
			ticker.Stop()
			fmt.Println("stopped")
			return
		}
	}
}

