import "fmt"

type Problem struct {
	Code int
}

func (p *Problem) Error() string {
	return fmt.Sprintf("problem %d", p.Code)
}

func find(fail bool) error {
	var p *Problem
	if fail {
		p = &Problem{Code: 7}
	}
	return p
}

func main() {
	err := find(false)
	fmt.Println(err == nil) // false: a typed nil inside an interface
	if err != nil {
		fmt.Println("caller sees a failure")
	}
}
